import{c as t,Q as o,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Output Discipline Rules","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-06-autoload-en/output-discipline.md","filePath":"research/reports/2026-06-06-autoload-en/output-discipline.md","lastUpdated":1780842316000}'),s={name:"research/reports/2026-06-06-autoload-en/output-discipline.md"};function a(r,e,l,u,c,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="output-discipline-rules" tabindex="-1">Output Discipline Rules <a class="header-anchor" href="#output-discipline-rules" aria-label="Permalink to &quot;Output Discipline Rules&quot;">​</a></h1><h2 id="core-output-rules" tabindex="-1">Core Output Rules <a class="header-anchor" href="#core-output-rules" aria-label="Permalink to &quot;Core Output Rules&quot;">​</a></h2><ul><li><strong>No preamble</strong>: Do not say &quot;of course&quot; / &quot;sure&quot; / &quot;here is&quot; etc. — occupies tokens without conveying information.</li><li><strong>Do not restate the question</strong>: Give the answer directly, skip &quot;Your question is...&quot; / &quot;Based on your needs...&quot;.</li><li><strong>Concise sentence style</strong>: Use bullet lists over prose when possible — higher scan efficiency, higher token density.</li><li><strong>Code minimalism</strong>: Only add comments for non-obvious logic — good naming is clearer than comments.</li><li><strong>Length limit</strong>: Plain text answers ≤ 150 words, exceptions: ① code block is the main body ② multi-step task checkpoint ③ complex system design explanation — over-length leads to drift.</li><li><strong>Filler words banned</strong>: just / really / basically / it&#39;s worth noting / as you can see / 值得注意的是 / 如您所見 / 事實上 — pure output bloat.</li><li><strong>Banned technical terms</strong>: leverage / robust / seamless / delve / utilize — banned in technical documents and code replies.</li><li><strong>Token efficiency (CJK tax countermeasure)</strong> (see refs/cjk-token-efficiency.md): Internal instructions/scratchpad/TODO may use English (CJK token inflation 2–3×); <strong>final responses to the user still maintain Taiwan Traditional Chinese</strong> (no silent fork of the Traditional Chinese rule).</li></ul><h2 id="elegance-self-check-exceptions" tabindex="-1">Elegance Self-Check + Exceptions <a class="header-anchor" href="#elegance-self-check-exceptions" aria-label="Permalink to &quot;Elegance Self-Check + Exceptions&quot;">​</a></h2><ul><li>After non-trivial changes, ask: &quot;Is there a more elegant solution?&quot; Yes → revert and improve; skip for trivial changes.</li><li><strong>Exceptions</strong>: ① Detailed explanation requested ② Tutorial documents (prose acceptable) ③ Casual tone (one-line confirmation) ④ Checkpoint → relax 150-word limit.</li></ul>',5)])])}const g=t(s,[["render",a]]);export{h as __pageData,g as default};
